  "👦 Garçon": ["👦 Boy", "👦 ولد", "👦 Cɛmancɛ", "👦 Suka gorko"],
  "👧 Fille": ["👧 Girl", "👧 بنت", "👧 Musomancɛ", "👧 Suka debbo"],
  "L'enfant est *": ["The child is *", "الطفل *", "Den ye *", "Ɓiɗɗo ko *"],
  "🌱 Vivant": ["🌱 Alive", "🌱 حي", "🌱 Ɲɛnama", "🌱 Wuurɗo"],
